    const st = c.pct === 100 ? ['Completed', '#DCFCE7', '#166534'] : c.pct > 0 ? ['In progress', '#FEF3C7', '#92400E'] : prevDone ? ['Next', '#DBEAFE', '#1E40AF'] : ['Locked', '#EAF1F6', '#526B7A'];
