    xpOpts: [20, 30, 50, 100].map(v => ({ v, border: bl.xp === v ? '#0066A1' : '#D7E3EC', bg: bl.xp === v ? '#EDF5FA' : '#FFFFFF', pick: () => this.updBl({ xp:v }) })),
