const CERT_C = { Certified:['#DCFCE7', '#166534'], 'Not certified':['#FDECEC', '#A63232'], 'In progress':['#FEF3C7', '#92400E'], 'No rule':['#EAF1F6', '#526B7A'], 'Not evaluated':['#EAF1F6', '#526B7A'] };

