    const lvl = !g || v == null ? null : k.dir === 'down' ? (v <= +k.green ? 0 : v <= +k.amber ? 1 : 2) : (v >= +k.green ? 0 : v >= +k.amber ? 1 : 2);
    // A formula can break later (a KPI it used was deleted or changed): show it instead of a silent —.
